/* Optional keys shown in MN04009E Figure 1, preserving the quick-start profile. */
const VisionBase=typeof module!=='undefined'?require('./hamilton-engine.js'):HamiltonClock;
class VisionTimeClock extends VisionBase {
 reset(){super.reset();this.shots={home:0,guest:0};this.timeoutTime=0;this.autoHorn=0;this.autoElapsed=0;}
 label(t){return {autoHorn:'AUTO HORN · SECONDS',teamTimeout:'TEAM TIME OUT · SECONDS',shots:'SHOTS ON GOAL'}[t]||super.label(t);}
 key(k){if(k==='auto'){this.field('autoHorn',this.autoHorn??0,240);return;}if(k.startsWith('timeout:')){this.running=false;this.field('teamTimeout',30,99,{side:k.split(':')[1]});return;}if(k.startsWith('shots:')){const side=k.split(':')[1],recalled=this.recall;this.recall=false;if(recalled)this.field('shots',this.shots[side],99,{side});else{this.shots[side]=Math.min(99,this.shots[side]+1);this.event('shots');}return;}if(k==='clear'&&this.edit?.type==='autoHorn'){this.edit.disableAll=true;this.edit.digits='';return;}return super.key(k);}
 enter(){const e=this.edit;if(!e)return;const n=e.digits===''?e.value:Number(e.digits);if(n<0||n>e.max){this.invalid('VALUE OUT OF RANGE');return;}if(e.type==='autoHorn'){this.autoHorn=e.disableAll?null:n;this.autoElapsed=0;this.done();return;}if(e.type==='teamTimeout'){this.timeoutTime=n;this.view=n===0?'game':'timeout';this.running=n>0;this.done(n===0?'GAME TIMER · HOLD':'TIME OUT · RUN');this.event(n===0?'timeoutend':'timeout');return;}if(e.type==='shots'){this.shots[e.side]=n;this.done();this.event('shots');return;}return super.enter();}
 tick(dt){if(this.view==='timeout'){if(this.running){this.timeoutTime=Math.max(0,this.timeoutTime-dt);if(this.timeoutTime===0){this.running=false;this.view='game';if(this.autoHorn!==null)this.event('horn');this.event('timeoutend');}}return;}const wasRunning=this.running,oldTime=this.time;super.tick(dt);if(this.autoHorn===null)this.events=this.events.filter(e=>e!=='horn');if(wasRunning&&this.view==='game'&&this.autoHorn>0){this.autoElapsed+=Math.abs(this.time-oldTime);if(this.autoElapsed>=this.autoHorn){this.autoElapsed%=this.autoHorn;this.event('horn');}}}
}
if(typeof module!=='undefined')module.exports=VisionTimeClock;
